import pytest


class TestGCDHappyPath:
    """Tests for typical, expected behavior of gcd function."""

    def test_gcd_basic_case(self):
        assert gcd(10, 5) == 5

    def test_gcd_common_divisor(self):
        assert gcd(54, 24) == 6

    def test_gcd_coprime_numbers(self):
        assert gcd(7, 13) == 1

    def test_gcd_unordered(self):
        assert gcd(12, 8) == gcd(8, 12) == 4

    def test_gcd_equal_numbers(self):
        assert gcd(42, 42) == 42

    def test_gcd_one_is_multiple_of_other(self):
        assert gcd(7, 42) == 7

    def test_gcd_result_equals_abs(self):
        # GCD should always be non-negative
        assert gcd(-15, 25) == 5
        assert gcd(15, -25) == 5


class TestGCDEdgeCases:
    """Tests for boundary conditions and edge cases."""

    def test_gcd_zero_first(self):
        assert gcd(0, 5) == 5

    def test_gcd_zero_second(self):
        assert gcd(5, 0) == 5

    def test_gcd_both_zero(self):
        # gcd(0, 0) is mathematically undefined, but the implementation returns 0
        assert gcd(0, 0) == 0

    def test_gcd_zero_and_negative(self):
        assert gcd(0, -7) == 7

    def test_gcd_negative_both(self):
        assert gcd(-12, -8) == 4

    def test_gcd_powers_of_two(self):
        assert gcd(32, 16) == 16

    def test_gcd_primes(self):
        assert gcd(97, 53) == 1


class TestGCDErrors:
    """Tests for invalid inputs and error handling."""

    def test_gcd_float_raises_type_error(self):
        with pytest.raises(TypeError):
            gcd(4.5, 3)

    def test_gcd_string_raises_type_error(self):
        with pytest.raises(TypeError):
            gcd("16", 8)

    def test_gcd_none_raises_type_error(self):
        with pytest.raises(TypeError):
            gcd(None, 5)

    def test_gcd_list_raises_type_error(self):
        with pytest.raises(TypeError):
            gcd([12], 6)

    def test_gcd_missing_argument_raises_error(self):
        with pytest.raises(TypeError):
            gcd(5)  # type: ignore

    def test_gcd_too_many_arguments_raises_error(self):
        with pytest.raises(TypeError):
            gcd(5, 3, 1)  # type: ignore


class TestGCDIntegration:
    """Integration tests comparing against Python's math.gcd."""

    @pytest.mark.parametrize("a, b", [
        (10, 5),
        (54, 24),
        (7, 13),
        (0, 42),
        (-12, 8),
        (1000000, 500000),
        (17, 289),
    ])
    def test_gcd_matches_math_gcd(self, a, b):
        assert gcd(a, b) == abs(math.gcd(a, b))
